"""Symmetric ansatz: H-invariant combinations (H generated by given permutations).
Variables: one coefficient per H-orbit of units; cost = orbit size.  Solutions
are re-solved exactly on the expanded support (solve.System.solve).
usage: python milp_sym.py N mode time_limit threads gens   (gens like "1,0,2,3,4;0,2,1,3,4")
"""
import pickle
import sys
import time

import highspy
import numpy as np

from solve import System, prune

N, MODE, TL, TH, GENS = int(sys.argv[1]), sys.argv[2], float(sys.argv[3]), int(sys.argv[4]), sys.argv[5]
gens = [tuple(int(t) for t in g.split(',')) for g in GENS.split(';')]
S = System(N)
SR = [S.Dm.shape[0] - 1] if MODE == 'top' else list(range(S.Dm.shape[0]))
idx = {k: i for i, k in enumerate(S.U)}


def norm(h, pairs):
    h = list(h); M = []
    for a, b in pairs:
        if a > b:
            h[a] += 1; h[b] -= 1; a, b = b, a
        M.append((a, b))
    return (tuple(h), frozenset(M))


def pk(key, p):
    h, M = key
    h2 = [0] * N
    for i in range(N):
        h2[p[i]] = h[i]
    return norm(h2, [(p[a], p[b]) for a, b in M])


orb = [-1] * S.n
orbits = []
for u in range(S.n):
    if orb[u] >= 0:
        continue
    o = [u]; orb[u] = len(orbits); st = [u]
    while st:
        v = st.pop()
        for g in gens:
            w = idx[pk(S.U[v], g)]
            if orb[w] < 0:
                orb[w] = len(orbits); o.append(w); st.append(w)
    orbits.append(o)
no = len(orbits)
print('orbits', no, flush=True)
# aggregated constraint rows: kink rows and D rows, columns = orbits
rows = []
for g in S.gkeys:
    acc = {}
    for u, lam in S.groups[g].items():
        acc[orb[u]] = acc.get(orb[u], 0) + lam
    acc = {o: v for o, v in acc.items() if v}
    if acc:
        rows.append((0.0, acc))
rows = list({tuple(sorted(a.items())): (b, a) for b, a in rows}.values())
for s in SR:
    acc = {}
    for u in range(S.n):
        if S.Dm[s, u]:
            acc[orb[u]] = acc.get(orb[u], 0) + int(S.Dm[s, u])
    rows.append((float(S.tD[s]), {o: v for o, v in acc.items() if v}))
BM = 4.0
h = highspy.Highs()
h.setOptionValue('time_limit', TL)
h.setOptionValue('threads', TH)
inf = highspy.kHighsInf
for _ in range(no):
    h.addVar(-BM, BM)
for _ in range(no):
    h.addVar(0, 1)
h.changeColsIntegrality(no, np.arange(no, 2 * no, dtype=np.int32), np.array([highspy.HighsVarType.kInteger] * no))
h.changeColsCost(no, np.arange(no, 2 * no, dtype=np.int32), np.array([float(len(o)) for o in orbits]))
for t, acc in rows:
    h.addRow(t, t, len(acc), np.array(list(acc), dtype=np.int32), np.array([float(v) for v in acc.values()]))
for i in range(no):
    h.addRow(-inf, 0, 2, np.array([i, no + i], dtype=np.int32), np.array([1.0, -BM]))
    h.addRow(-inf, 0, 2, np.array([i, no + i], dtype=np.int32), np.array([-1.0, -BM]))
t0 = time.time()
h.run()
info = h.getInfo()
print('status', h.modelStatusToString(h.getModelStatus()), 'obj', info.objective_function_value,
      'bound', info.mip_dual_bound, 't', round(time.time() - t0), flush=True)
x = h.getSolution().col_value
K = [u for i in range(no) if x[no + i] > 0.5 and abs(x[i]) > 1e-9 for u in orbits[i]]
sol = S.solve(K, SR)
print('expanded support', len(K), 'exact feasible', sol is not None)
if sol is not None:
    K2 = [u for u in K if sol.get(u, 0) != 0]
    tag = GENS.replace(',', '').replace(';', '_')
    pickle.dump({'N': N, 'mode': MODE, 'K': [S.U[u] for u in K2], 'd': {S.U[u]: sol[u] for u in K2}},
                open(f'data/sym_{N}_{MODE}_{tag}.pkl', 'wb'))
    print('exact support (one solution)', len(K2))
